ALTER TABLE public.promise_sources ADD COLUMN title text;
ALTER TABLE public.promise_evidence ADD COLUMN title text;
ALTER TABLE public.evidence_reviews ADD COLUMN sequence bigint GENERATED ALWAYS AS IDENTITY;
CREATE OR REPLACE FUNCTION public.evidence_is_public(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT r.decision='approved' AND p.published FROM public.promise_evidence e JOIN public.political_promises p ON p.id=e.promise_id JOIN public.evidence_reviews r ON r.evidence_id=e.id WHERE e.id=_id ORDER BY r.sequence DESC LIMIT 1),false) $$;
CREATE FUNCTION public.assessment_supported(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.promise_assessments a WHERE a.id=_id AND (a.status='ainda não avaliável' AND a.fulfillment_percent IS NULL OR cardinality(a.evidence_ids)>0) AND NOT EXISTS(SELECT 1 FROM unnest(a.evidence_ids) eid WHERE NOT public.evidence_is_public(eid))) $$;
ALTER POLICY visible_assessments ON public.promise_assessments USING((verification='approved' AND public.assessment_supported(id) AND EXISTS(SELECT 1 FROM public.political_promises p WHERE p.id=promise_id AND p.published)) OR submitted_by=auth.uid() OR public.is_promise_reviewer());
CREATE FUNCTION public.require_contributor(reviewer boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta para contribuir'; END IF; IF reviewer AND NOT public.is_promise_reviewer() THEN RAISE EXCEPTION 'Acesso exclusivo de revisores autorizados'; END IF; RETURN auth.uid(); END $$;
CREATE FUNCTION public.validate_assessment(s public.promise_status,p numeric,ids uuid[],pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF p IS NOT NULL AND (p<0 OR p>100 OR s='ainda não avaliável' OR s='cumprida' AND p<>100 OR s='não cumprida' AND p<>0 OR s='parcialmente cumprida' AND (p<=0 OR p>=100) OR s='em andamento' AND p>=100) THEN RAISE EXCEPTION 'Percentual incompatível com a situação'; END IF;
IF s<>'ainda não avaliável' AND cardinality(ids)=0 THEN RAISE EXCEPTION 'A avaliação exige evidências aprovadas'; END IF;
IF EXISTS(SELECT 1 FROM unnest(ids) eid WHERE NOT EXISTS(SELECT 1 FROM public.promise_evidence e WHERE e.id=eid AND e.promise_id=pid AND public.evidence_is_public(e.id))) THEN RAISE EXCEPTION 'Evidência não aprovada ou de outra promessa'; END IF;
END $$;
CREATE FUNCTION public.submit_evidence(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_contributor(); result uuid; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.political_promises WHERE id=(payload->>'promise_id')::uuid AND published) THEN RAISE EXCEPTION 'Promessa não disponível'; END IF;
INSERT INTO public.promise_evidence(promise_id,submitted_by,description,url,publisher,title,provenance,quotation,published_on,accessed_on,timestamp_start,timestamp_end) VALUES((payload->>'promise_id')::uuid,uid,trim(payload->>'description'),payload->>'url',payload->>'publisher',payload->>'title',COALESCE((payload->>'provenance')::public.source_provenance,'unknown'),payload->>'quotation',NULLIF(payload->>'published_on','')::date,NULLIF(payload->>'accessed_on','')::date,NULLIF(payload->>'timestamp_start','')::integer,NULLIF(payload->>'timestamp_end','')::integer) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.review_evidence(evidence uuid,decision public.verification_state,rationale text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_contributor(true); result uuid; BEGIN
PERFORM 1 FROM public.promise_evidence WHERE id=evidence FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Evidência não encontrada'; END IF;
INSERT INTO public.evidence_reviews(evidence_id,decision,reviewer_id,rationale) VALUES(evidence,decision,uid,trim(rationale)) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.submit_assessment(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_contributor(); pid uuid:=(payload->>'promise_id')::uuid; s public.promise_status:=(payload->>'status')::public.promise_status; pct numeric:=NULLIF(payload->>'fulfillment_percent','')::numeric; ids uuid[]; result uuid; previous uuid; v integer; BEGIN
PERFORM 1 FROM public.political_promises WHERE id=pid AND published FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Promessa não disponível'; END IF;
SELECT COALESCE(array_agg(value::uuid),'{}') INTO ids FROM jsonb_array_elements_text(COALESCE(payload->'evidence_ids','[]'));
PERFORM public.validate_assessment(s,pct,ids,pid);
SELECT id,version INTO previous,v FROM public.promise_assessments WHERE promise_id=pid ORDER BY version DESC LIMIT 1;
INSERT INTO public.promise_assessments(promise_id,version,status,fulfillment_percent,criteria,methodology,rationale,evidence_ids,submitted_by,supersedes) VALUES(pid,COALESCE(v,0)+1,s,pct,trim(payload->>'criteria'),trim(payload->>'methodology'),trim(payload->>'rationale'),ids,uid,previous) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.review_assessment(assessment uuid,decision public.verification_state,rationale text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_contributor(true); a public.promise_assessments; result uuid; v integer; BEGIN
SELECT * INTO a FROM public.promise_assessments WHERE id=assessment; IF NOT FOUND OR a.verification<>'pending' THEN RAISE EXCEPTION 'Avaliação pendente não encontrada'; END IF;
PERFORM 1 FROM public.political_promises WHERE id=a.promise_id FOR UPDATE;
IF EXISTS(SELECT 1 FROM public.promise_assessments WHERE supersedes=a.id AND verification<>'pending') THEN RAISE EXCEPTION 'Avaliação já revisada'; END IF;
IF decision='pending' THEN RAISE EXCEPTION 'Selecione aprovar ou rejeitar'; END IF;
IF decision='approved' THEN PERFORM public.validate_assessment(a.status,a.fulfillment_percent,a.evidence_ids,a.promise_id); END IF;
SELECT max(version)+1 INTO v FROM public.promise_assessments WHERE promise_id=a.promise_id;
INSERT INTO public.promise_assessments(promise_id,version,status,fulfillment_percent,criteria,methodology,rationale,evidence_ids,verification,submitted_by,reviewer_id,reviewed_at,supersedes) VALUES(a.promise_id,v,a.status,a.fulfillment_percent,a.criteria,a.methodology,trim(rationale),a.evidence_ids,decision,a.submitted_by,uid,now(),a.id) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.create_promise(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_contributor(true); result uuid; src jsonb:=payload->'source'; BEGIN
IF src->>'url' IS NULL THEN RAISE EXCEPTION 'Inclua a fonte da promessa'; END IF;
INSERT INTO public.political_promises(politician_id,title,description,category,promised_on,deadline,date_uncertainty,published,created_by) VALUES(payload->>'politician_id',trim(payload->>'title'),COALESCE(payload->>'description',''),COALESCE(payload->>'category','Outros'),NULLIF(payload->>'promised_on','')::date,NULLIF(payload->>'deadline','')::date,payload->>'date_uncertainty',true,uid) RETURNING id INTO result;
INSERT INTO public.promise_sources(promise_id,url,title,publisher,provenance,quotation,published_on,accessed_on,timestamp_start,timestamp_end,published) VALUES(result,src->>'url',src->>'title',src->>'publisher',COALESCE((src->>'provenance')::public.source_provenance,'unknown'),src->>'quotation',NULLIF(src->>'published_on','')::date,NULLIF(src->>'accessed_on','')::date,NULLIF(src->>'timestamp_start','')::integer,NULLIF(src->>'timestamp_end','')::integer,true); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.require_contributor(boolean),public.validate_assessment(public.promise_status,numeric,uuid[],uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.submit_evidence(jsonb),public.review_evidence(uuid,public.verification_state,text),public.submit_assessment(jsonb),public.review_assessment(uuid,public.verification_state,text),public.create_promise(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_evidence(jsonb),public.review_evidence(uuid,public.verification_state,text),public.submit_assessment(jsonb),public.review_assessment(uuid,public.verification_state,text),public.create_promise(jsonb) TO authenticated;
CREATE FUNCTION public.promise_catalog() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('promises',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id) FROM public.political_promises p),'[]'),'politicians',COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM public.politicians p),'[]'),'sources',COALESCE((SELECT jsonb_agg(to_jsonb(s)) FROM public.promise_sources s),'[]'),'assessments',COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM public.promise_assessments a),'[]'),'evidence',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM public.promise_evidence e),'[]'),'reviews',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.evidence_reviews r),'[]')) $$;
GRANT EXECUTE ON FUNCTION public.promise_catalog() TO anon,authenticated;